add_filter( 'woocommerce_is_purchasable', 'perfectpixel_purchase_once', 10, 2 );
add_filter( 'woocommerce_variation_is_purchasable', 'perfectpixel_purchase_once', 10, 2 );

function perfectpixel_purchase_once( $purchasable, $product ) {
	if ( ! $purchasable || ! is_user_logged_in() ) {
		return $purchasable;
	}
	$product_id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	$limited    = wp_parse_id_list( '{{once_product_ids}}' );
	if ( $limited && ! in_array( $product_id, $limited, true ) ) {
		return $purchasable;
	}
	$user = wp_get_current_user();
	if ( wc_customer_bought_product( $user->user_email, $user->ID, $product_id ) ) {
		return false;
	}
	return $purchasable;
}
